+// RF-005: anula una factura emitida con un motivo obligatorio. Devuelve una factura nueva; la original no cambia.
+export function anularFactura(factura, motivo) {
+  if (typeof motivo !== "string" || motivo.trim() === "") throw new Error("La anulación exige un motivo");
+  if (factura?.estado !== "emitida") throw new Error("Solo se puede anular una factura emitida");
+  return Object.freeze({ ...factura, estado: "anulada", motivoAnulacion: motivo.trim() });
+}
