+test("RF-005: anular produce una factura nueva 'anulada' con motivo y no altera la original", () => {
+  const original = emitirFactura({ numero: 9, nit: "1023456", razonSocial: "Cliente SA", items: [{ cantidad: 1, precioUnitarioCentavos: 1000 }] });
+  const anulada = anularFactura(original, "Error en la razón social");
+  assert.notEqual(anulada, original);
+  assert.equal(anulada.estado, "anulada");
+  assert.equal(anulada.motivoAnulacion, "Error en la razón social");
+  assert.equal(anulada.numero, original.numero);
+  assert.equal(anulada.totalCentavos, original.totalCentavos);
+  assert.ok(Object.isFrozen(anulada));
+  assert.equal(original.estado, "emitida");
+  assert.equal(original.motivoAnulacion, undefined);
+});
+
+test("RF-005: la anulación exige motivo", () => {
+  const f = emitirFactura({ numero: 10, nit: "1023456", razonSocial: "X", items: [{ cantidad: 1, precioUnitarioCentavos: 100 }] });
+  assert.throws(() => anularFactura(f));
+  assert.throws(() => anularFactura(f, ""));
+  assert.throws(() => anularFactura(f, "   "));
+});
+
